                               (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            grid[nr][nc] == color and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            top = min(rr for rr, _ in cells)
            left = min(cc for _, cc in cells)
            bh = max(rr for rr, _ in cells) - top + 1
            bw = max(cc for _, cc in cells) - left + 1
            shape = {(rr - top, cc - left) for rr, cc in cells}

            frame = bh >= 3 and bw >= 3
            if frame:
                for rr in range(bh):
                    for cc in range(bw):
                        border = rr == 0 or rr == bh - 1 or cc == 0 or cc == bw - 1
                        if border != ((rr, cc) in shape):
                            frame = False
                            break
                    if not frame:
                        break

            objects.append({
                "color": color, "top": top, "left": left,
                "bh": bh, "shape": shape, "frame": frame
            })

    placed = []
    # Move frames upward, and all other objects downward. Objects only
    # block movement by other objects in the same group.
    for is_frame, direction in ((True, -1), (False, 1)):
        group = [o for o in objects if o["frame"] == is_frame]
        if direction == -1:
            group.sort(key=lambda o: o["top"])
        else:
            group.sort(key=lambda o: -(o["top"] + o["bh"]))

        group_placed = []
        for o in group:
            y = o["top"]
            x = o["left"]

            def collides(test_y):
                for other, oy, ox in group_placed:
                    other_cells = {(oy + dr, ox + dc) for dr, dc in other["shape"]}
                    if any((test_y + dr, x + dc) in other_cells
                           for dr, dc in o["shape"]):
                        return True
                return False

            while True:
                next_y = y + direction
                if next_y < 0 or next_y + o["bh"] > h or collides(next_y):
                    break
                y = next_y

            group_placed.append((o, y, x))
            placed.append((o, y, x))

    out = [[0] * w for _ in range(h)]
    for o, y, x in placed:
        for dr, dc in o["shape"]:
            out[y + dr][x + dc] = o["color"]
